import{r as e,t}from"./jsx-runtime-BkSabwWG.js";import{t as n}from"./react-DHmoMYoq.js";var l=e(n(),1),h=t();
var P={"1":[{"b":"Hand drum","i":[[4,"Name wave","Sing “Hello, _____” on so–mi; the class echoes. Get through as many names as fit, then “Hello, Grade One.”"],[5,"How we do music + Sit like a singer","We sing, play, move, listen. Model feet on the floor, tall backs, hands in laps, at desks or on the carpet."],[6,"The quiet hand","Talk, hand up, freeze. Practise three times and smile at the freeze. Tap the hand drum as the “start” sound."],[5,"Read-aloud · The Listening Walk","Hook from the book guide. Stop at the park if time runs out; finish in Class 2."]]},{"b":"Hand drum","i":[[4,"Name wave","Finish the names you missed in Class 1."],[3,"Read-aloud · finish The Listening Walk","Or retell it quickly if you finished. Ask what sounds they noticed."],[7,"A hello song","Teach “Hello Everybody” by echo, phrase by phrase, then the whole thing. Start it from your voice at a light, child-friendly pitch (not an adult low voice)."],[6,"Echo the teacher","Clap 4-beat patterns, class claps back. Use the quiet hand between echoes."]]},{"b":"Hand drum","i":[[3,"Hello song","Sing “Hello Everybody” standing."],[8,"Echo the teacher (extended)","4-beat claps, then 4-beat so–mi snippets on “loo.” Repeat the game longer today so everyone settles into echo."],[4,"Quiet-hand check","Talk, hand up, freeze three times with no reminder. Try the Challenge: one student leads a tiny clap."],[5,"Close + Check","“What does the quiet hand mean?” Go through the Check list. Stamp the lesson if most freeze without a reminder."]]}],"2":[{"b":"No instruments (voices and body percussion)","i":[[5,"Four voices","Whisper, speak, call, then sing “good morning” on so–mi. Students copy each one and name it."],[6,"Talking sits, singing floats","Hand on chest for talk, on head for sing. Say and sing “hello” both ways."],[3,"We do not shout songs","If it gets loud, drop to a whisper-sing so they follow."],[6,"Read-aloud · Mortimer","Use the book guide’s listening focus."]]},{"b":"No instruments (voices and body percussion)","i":[[4,"Four voices","Quick replay, students lead one voice each round."],[6,"Match my pitch","Sing so on “loo,” then mi, then so–mi. If you want a reference pitch, tap it on the site’s Music Studio piano on the classroom screen. Nod at close matches; don’t single anyone out."],[6,"Song: Rain, Rain","Echo by phrase. Add gentle finger rain. Use the score on the page."],[4,"Optional story · Mina’s two voices","Read the short story from the page and ask which voice Mina used."]]},{"b":"No instruments (voices and body percussion)","i":[[4,"Rain, Rain","Sing it through with finger rain."],[8,"Sort the voice","Say or sing a line; students show chest (talk) or head (sing). Mix them up, then sing Rain, Rain all the way through."],[3,"Practice studio · piano","Play so and mi on the site’s Music Studio piano on the classroom screen; the class matches with voices."],[5,"Close + Check","Two students show talk, then sing, on “hello.” Go through the Check list and stamp."]]}],"3":[{"b":"Hand drum, 1 woodblock","i":[[5,"Copy cat claps","Four-beat claps, class echoes. Start with ta ta ta ta, then add one rest."],[5,"Echo means copy","I go, you go. Same speed, same number, same tune. No extra claps."],[5,"Voice echo","Sing so–mi on “yoo.” Change the last note sometimes so they listen, not guess."],[5,"Hello song review","Sing “Hello Everybody” from week 1 as an echo song."]]},{"b":"Hand drum, 1 woodblock","i":[[4,"Copy cat claps","Echo on the hand drum and woodblock: you play, they clap it back."],[7,"Engine, Engine","Chant with a steady beat on laps, then sing the so–mi first line. Echo by two bars."],[6,"Read-aloud · From Head to Toe","Brain break standing beside desks, per the book guide."],[3,"Voice echo","Three quick so–mi “yoo” echoes to settle."]]},{"b":"Hand drum, 1 woodblock","i":[[3,"Engine, Engine","Chant and sing it through."],[3,"Alone and together","One brave child leads a clap echo. Sitting is fine."],[9,"Leader for a turn","Circle. You lead three echoes, then students each lead one clap pattern. Pass the hand drum to the leader. Finish with Engine, Engine together."],[5,"Close + Check","“Does an echo add extra sounds?” No. Go through the Check list; stamp if echoes stay the same length."]]}],"4":[{"b":"No instruments (voices and body percussion). Music Studio on the screen","i":[[4,"Elevator","Hands low, hum mi; hands high, hum so. Ride it three times. Give the pitches with your voice."],[7,"So is higher, mi is lower","Show the so and mi hand signs. Copy them silently, then with “so” and “mi.”"],[5,"I sing, you sign","You sing so or mi, they sign. Then reverse: you sign, they sing."],[4,"Do not stretch so too high","If so looks like a strain, start the song lower. Check it on the site’s Music Studio piano on the classroom screen if you like. Sing so–mi hellos."]]},{"b":"No instruments (voices and body percussion). Music Studio on the screen","i":[[3,"Elevator","Quick replay."],[5,"I sing, you sign","Faster rounds, then a student sings for the class to sign."],[7,"See-Saw","Echo, then all, with a gentle knee bend on the beat. Use the score on the page."],[5,"Practice studio · piano","Find so and mi on the site’s Music Studio piano on the classroom screen. A few students take turns tapping while the class signs."]]},{"b":"No instruments (voices and body percussion). Music Studio on the screen","i":[[3,"See-Saw","Sing it through with knee bends."],[8,"Sign the song","Sing See-Saw with so and mi signs. Students take turns as the “hand teacher.”"],[5,"Book · Rain, Rain, Go Away!","Sing the book (it is the song), with signs."],[4,"Close + Check","Silent hand signs: class sings what they see, two patterns. Go through the Check list and stamp."]]}],"5":[{"b":"No instruments. Beanbag for the game","i":[[5,"Bounce High, Bounce Low","Seated bounce on the beat, then standing beside desks. Swap in a class name."],[4,"A singing game has a job","We sing the whole time. If the tune falls apart: freeze, sing once sitting, play again."],[7,"Read-aloud · We're Going on a Bear Hunt","Brain break in a circle at the carpet, per the book guide."],[4,"Still a singing voice","Light voice, strong beat in the feet. Sing Bounce High once more that way."]]},{"b":"No instruments. Beanbag for the game","i":[[3,"Bounce High","Standing, with a class name."],[7,"Lucy Locket","Teach it by echo, then circle up at the carpet. One child walks the beat around the outside of the circle with the beanbag and drops it behind a friend."],[3,"Kind turns","Everyone gets a turn over the year. No grabbing. No “you missed.”"],[7,"Play the game","Lucy Locket again; sit after two or three turns to reset the tune, then play on."]]},{"b":"No instruments. Beanbag for the game","i":[[3,"Bounce High","Seated bounce to settle."],[10,"Play the game (extended)","Your choice of Lucy Locket or Bounce High, played longer so more children get a turn. Reset the tune sitting between rounds."],[3,"Challenge duet","A pair sings Bounce High while the class pats the beat."],[4,"Close + Check","Sit and sing the song once with no game. Go through the Check list. Stamp if the tune survived the game."]]}],"6":[{"b":"No instruments (voices and body percussion)","i":[[4,"Start and stop","Breathe together. Hand in: “loo” on so. Hand out: rest. Four tries."],[6,"Read-aloud · Pete the Cat: I Love My White Shoes","Hook before polishing, per the book guide. Sing the refrain with the class."],[4,"Unison means one tune","Match your neighbour. If you can’t hear them, you’re too loud."],[6,"Polish the class song","Words, then tune, then both. Fix one sticky phrase by echo."]]},{"b":"No instruments (voices and body percussion)","i":[[3,"Start and stop","Four more tries with a cleaner cut-off."],[3,"Standing tall","Feet quiet, faces toward the conductor, hands still."],[9,"Polish the class song","Fix a second sticky bar, then two practice runs."],[5,"Project 1 · practice run","One run as if someone is listening. Celebrate the stop as much as the start."]]},{"b":"No instruments (voices and body percussion)","i":[[3,"Start and stop","Warm up the cut-off."],[4,"Project 1 · practice run","One more run standing."],[5,"One sharing take","The sharing run. Optional: record it on a classroom device."],[4,"Play back or sing again","Listen to the recording, or sing it once more. Try the Challenge: one action on a word."],[4,"Close + Check","Name one thing the class did well. Go through the Check list. Stamp Project 1 if the sharing run held together."]]}],"7":[{"b":"Hand drum","i":[[5,"Heartbeat","Hand on chest. Play a slow, steady hand drum; students pat that speed on their legs."],[5,"Read-aloud · Hand, Hand, Fingers, Thumb","Hook from the book guide. It is short, so read it twice and pat the beat the second time."],[6,"Beat does not stop for big words","“Cat, cat, cat, cat,” then “elephant, cat…”. The pats stay even."],[4,"Show it three ways","Pat, step in place, quiet two-finger clap. Switch on your cue."]]},{"b":"Hand drum, shakers, woodblocks","i":[[3,"Heartbeat","Hand drum beat, class pats."],[6,"Song on top","Sing Engine, Engine or Rain, Rain while patting. If pats follow the words, go back to drum only."],[5,"The beat can be slow or faster","Two tempos only on the hand drum. Still even."],[1,"Instruments out & back","Hand out shakers and woodblocks in rest position; collect them the same way at the end."],[5,"Shakers and woodblocks on the beat","Students play the steady beat with your hand drum. Rest position between songs."]]},{"b":"Hand drum, shakers, woodblocks","i":[[3,"Show it three ways","Pat, step, clap on cue."],[1,"Instruments out & back","Hand out shakers and woodblocks in rest position; collect them the same way at the end."],[8,"Drum is the boss","Your hand drum leads; students match on shakers and woodblocks. Fade the drum and see if they stay even. Bring it back if they rush."],[3,"Practice studio · rhythm","Play the page’s beat grid; class pats along."],[5,"Close + Check","A student plays four even beats on the hand drum while the class pats. Collect instruments. Go through the Check list and stamp."]]}],"8":[{"b":"Hand drum","i":[[4,"Seat beat, then stand","Eight pats sitting, eight steps standing. Check shoes and space."],[7,"Walk the drum","Play even beats on the hand drum. Students walk the beat in a circle at the carpet (or step in place beside desks). Soft knees, own space."],[5,"Freeze is part of music","Drum stops, feet stop. Practise five times."],[4,"Walk and stop song","Sing Walk and Stop from the scores, stepping the beat in place beside desks."]]},{"b":"Hand drum","i":[[3,"Seat beat, then stand","Quick replay."],[6,"The song walks too","Sing Engine, Engine while walking the carpet circle. If they skip to the words, go back to drum only."],[4,"Directions","Forward around the circle, turn around, back to your spot by the last phrase."],[7,"Read-aloud · Giraffes Can't Dance","Brain break standing beside desks, per the book guide."]]},{"b":"Hand drum, tambourine","i":[[3,"Walk the drum","Warm up with the hand drum."],[10,"Walk and freeze","Three songs or drum grooves around the carpet circle (hand drum, then tambourine for a new sound). Freeze on silence. Walk home and sit on the last beat."],[3,"Challenge · quiet leader","Four students match a leader’s steps with no drum."],[4,"Close + Check","Seated: “Did your feet follow the drum or the words?” Go through the Check list and stamp."]]}],"9":[{"b":"No instruments. HANDS / FEET cards","i":[[5,"Simon beat","Beat in hands, quiet feet, shoulders; change every eight beats. Freeze on “rest.”"],[5,"The beat can move around the body","Same even heart, new place."],[4,"Shoulders and heads are gentle","Two fingers. Model the volume."],[6,"Read-aloud · Noisy Nora","Per the book guide."]]},{"b":"No instruments. HANDS / FEET cards","i":[[4,"Simon beat","Faster switches."],[8,"Sing on top","Teddy Bear or Acka Backa from the scores (or See-Saw). Point to hands or feet; the song keeps going."],[3,"Freeze is a rest for the body","Freeze on your cue mid-song, then carry on."],[5,"Cue-card beat · first try","You hold HANDS / FEET cards while they sing."]]},{"b":"No instruments. HANDS / FEET cards","i":[[3,"Simon beat","Warm up."],[9,"Cue-card beat","A student helper holds HANDS or FEET; you control freeze. Rotate the helper often."],[4,"Challenge","Switch every four beats instead of eight. Still even?"],[4,"Close + Check","Name a child who changed on the first try. Go through the Check list and stamp."]]}],"10":[{"b":"Hand drum, 1 woodblock","i":[[4,"March in place","STRONG, quiet, STRONG, quiet. Keep it small so knees stay safe."],[4,"Strong is not shout","A tiny knee bend on 1. Heavier, not angry."],[6,"Groups of 2","See-Saw: bend on “See,” light on “saw.” Then pat-clap (pat is strong)."],[6,"Read-aloud · The Loud Book!","Per the book guide."]]},{"b":"Hand drum, 1 woodblock","i":[[3,"March in place","Quick replay."],[7,"Groups of 4","Engine, Engine: beat 1 stronger, 2 3 4 light. Play beat 1 on the hand drum, 2 3 4 on a woodblock."],[5,"Conducting","Your hand is bigger on the strong beat; bodies match."],[5,"Practice studio · rhythm","Pat-clap along with the beat grid on the page."]]},{"b":"Hand drum, 1 woodblock","i":[[3,"Groups of 2","See-Saw pat-clap."],[9,"Statue on 1","Step the beat in place beside desks. On each strong beat, a tiny freeze-frame. Then sit and pat-clap a known song."],[3,"Challenge","A student conducts: big hand on 1, small hands on the rest."],[5,"Close + Check","“Is the strong beat the yelling beat?” Go through the Check list and stamp."]]}],"11":[{"b":"No instruments (voices and body percussion)","i":[[5,"Two jobs","Half the class pats even beats, half speaks “Engine, engine, number nine.” Swap."],[5,"Give them names","Beat is the even heart. Rhythm is the way the words go. Today we feel the difference."],[4,"Draw it","Four even dots; write the chant underneath and swoop the syllables."],[6,"Read-aloud · Chicka Chicka Boom Boom","Hook just before Hands vs laps, per the book guide."]]},{"b":"No instruments (voices and body percussion)","i":[[4,"Two jobs","Swap roles."],[7,"Hands vs laps","Laps keep the beat, hands tap the words. Go slowly; mixing them up is part of learning."],[5,"Song check","Rain, Rain: beat on laps, then words on shoulders. Which stayed even?"],[4,"Draw it again","Point to the dots while the class chants; add Rain, Rain under dots."]]},{"b":"Hand drum, shakers, woodblocks","i":[[3,"Two jobs","Warm up."],[1,"Instruments out & back","Hand out shakers and woodblocks in rest position; collect them the same way at the end."],[8,"Split the class","Line A plays the beat on woodblocks (you keep it on the hand drum); Line B taps the words on shakers. Conduct them in and out, then swap. End with everyone on the beat only."],[3,"Challenge","Tap the words of your name. Does it fit in four beats?"],[5,"Close + Check","“Which one is even?” Beat. Go through the Check list and stamp."]]}],"12":[{"b":"Hand drum, shakers, woodblocks, triangle, tambourine","i":[[4,"Silent parade","Walk the beat quietly in a loop around the carpet (or the desk aisles). Hand drum only. Freeze. Sit."],[4,"What “done” looks like","Even feet or even instrument. Freeze on stop. Instruments quiet until the start hand."],[7,"Read-aloud · Max Found Two Sticks","Hook, per the book guide. Tap the beat on laps as you read."],[1,"Instruments out & back","Hand out shakers and woodblocks in rest position; collect them the same way at the end."],[4,"If you have a shaker or sticks","Play the beat on shakers and woodblocks, not the words. Quiet volume."]]},{"b":"Hand drum, shakers, woodblocks, triangle, tambourine","i":[[3,"Silent parade","Warm up."],[6,"The song is the street","You sing (Walk and Stop or Engine, Engine) and the parade moves around the carpet loop. Drum stops = statues."],[5,"Audience spots","Half parade, half watch from their desks. Watchers check: even? safe? freeze? Swap."],[1,"Instruments out & back","Hand out shakers, woodblocks, triangle, tambourine in rest position; collect them the same way at the end."],[5,"Project 2 · rehearsal parade 1","Shakers, woodblocks, triangle and tambourine on the beat around the carpet loop; you lead on the hand drum."]]},{"b":"Hand drum, shakers, woodblocks, triangle, tambourine","i":[[3,"Silent parade","Warm up."],[1,"Instruments out & back","Hand out the parade instruments in rest position; collect them the same way at the end."],[4,"Project 2 · rehearsal parade 2","Fix freezes and instrument care."],[6,"Project 2 · sharing parade","Watchers give one kind comment: “I saw even feet.”"],[2,"Challenge","A student plays the beat on the hand drum while the class walks."],[4,"Close + Check","Collect instruments carefully. Go through the Check list and stamp Project 2."]]}],"13":[{"b":"Triangle, 1 woodblock","i":[[4,"Stretch and tap","Long “oooo” with arms opening, then two short “ti ti” finger taps. Alternate."],[4,"Read-aloud · Charlie Parker Played Be Bop","Very short: read or play it twice, per the book guide."],[7,"Long takes more time","Hold “luuuu”; short is “ti-ti.” One long sound for one step, two quick sounds for one step."],[5,"Names come next week","Today just long and short. Ear game: you ring the triangle (long) or tap the woodblock (short twice); students show arms or fingers."]]},{"b":"Triangle, 1 woodblock","i":[[3,"Stretch and tap","Warm up."],[6,"Draw icons","A long macaroni, two little dots. Students draw a few on paper."],[5,"Song hunt","Sing Rain, Rain or Pease Porridge Hot. Which words feel longer?"],[6,"Practice studio · rhythm","Build long/short patterns on the page’s beat grid; class claps them."]]},{"b":"Triangle, 1 woodblock","i":[[3,"Stretch and tap","Warm up."],[10,"Compose with yarn","Pairs lay one long or two shorts in each of four beats on their desk (yarn or paper strips). Clap it. Switch with a neighbour."],[3,"Challenge","Sing your four-beat picture on so–mi."],[4,"Close + Check","Class claps one pair’s pattern. Go through the Check list; stamp if they can tell long from short by ear."]]}],"14":[{"b":"No instruments (voices and body percussion)","i":[[4,"Four tas","Say “ta ta ta ta” while stepping. Clap it. Whisper it."],[6,"Ta is one sound on one beat","Point to four tas on the board; students write them in the air."],[4,"Icon they can draw","Pick one ta icon and stay with it all year."],[6,"Find ta in a chant","“One, two, tie my shoe.” Pat and say ta, then put the words back. Try Pease Porridge Hot too."]]},{"b":"Shakers, woodblocks","i":[[3,"Four tas","Warm up."],[1,"Instruments out & back","Hand out woodblocks and shakers in rest position; collect them the same way at the end."],[5,"Read a line","Board: ta ta ta ta. Class reads it, then plays it on woodblocks and shakers."],[7,"Read-aloud · This Jazz Man","Brain break, per the book guide. Sing it to “This Old Man.”"],[4,"Practice studio · rhythm","Show four tas on the page’s beat grid; class reads and pats."]]},{"b":"Shakers, woodblocks","i":[[3,"Four tas","Warm up."],[1,"Instruments out & back","Hand out shakers in rest position; collect them the same way at the end."],[9,"Write four tas","On the worksheet or mini whiteboards. Swap with a neighbour and read theirs. Play them on laps or shakers."],[2,"Challenge","Conduct four tas with a straight finger, left to right."],[5,"Close + Check","One child points, class says ta. Go through the Check list and stamp."]]}],"15":[{"b":"No instruments (voices and body percussion)","i":[[4,"Slow ta, quick ti-ti","Step ta in place beside desks, then two quick toe taps for ti-ti on the same beat speed (finger taps work too)."],[6,"Read-aloud · Tanka Tanka Skunk!","Hook for Teach, per the book guide. Clap the drumming words."],[5,"Ti-ti shares the beat","One ta is a sandwich, ti-ti is two halves on the same plate."],[5,"Draw two little notes together","Two sticks with a beam, matching week 14’s icon style."]]},{"b":"Shakers, woodblocks","i":[[3,"Slow ta, quick ti-ti","Warm up."],[6,"Pease Porridge Hot","Clap the words. Find the quick pairs and say them as ti-ti. Keep the beat in the feet."],[1,"Instruments out & back","Hand out woodblocks and shakers in rest position; collect them the same way at the end."],[6,"Read mixed lines","ta ta ti-ti ta. Point. Play them on woodblocks and shakers."],[4,"Acka Backa","Sing or chant it from the scores and find its ti-tis."]]},{"b":"No instruments (voices and body percussion)","i":[[3,"Read mixed lines","Two lines on the board."],[9,"Build a bar","Four beat boxes on paper; fill each with ta or ti-ti. Clap. Trade papers."],[3,"Challenge","A student teaches their ta/ti-ti pattern to their row."],[5,"Close + Check","Ear quiz: you clap ta or ti-ti; they show one finger or two. Go through the Check list and stamp."]]}],"16":[{"b":"No instruments (voices and body percussion)","i":[[4,"Play, rest, play, rest","Clap, open hands, clap, open hands. Faces stay ready."],[6,"Rest is a beat with no sound","We feel it; we don’t skip it. Finger on lips or open palms."],[5,"Write it","Pick one rest symbol for the class."],[5,"Read-aloud · The Quiet Book","Per the book guide."]]},{"b":"Hand drum, woodblocks","i":[[3,"Play, rest, play, rest","Warm up."],[1,"Instruments out & back","Hand out woodblocks in rest position; collect them the same way at the end."],[6,"Read ta ta rest ta","Stay still for the full beat. Read it on woodblocks while you keep the beat on the hand drum."],[6,"Put a rest in a known chant","Beat 4 silent in Engine, Engine or Pease Porridge Hot. Giggle once, then make the silence real."],[4,"Practice studio · rhythm","Put rests on the page’s beat grid and read the lines together."]]},{"b":"No instruments (voices and body percussion)","i":[[3,"Read ta ta rest ta","Warm up."],[10,"Mystery rest","Clap a four-beat pattern with one rest; students point to the silent beat. Then they write their own with one rest and perform."],[2,"Challenge","A pattern with two rests that still feels like music."],[5,"Close + Check","Class statue for one full rest. Go through the Check list and stamp."]]}],"17":[{"b":"No instruments (voices and body percussion)","i":[[5,"Flash cards","All tas; ta ti-ti ta ta; ta ta sh ta. See, wait, clap."],[5,"Eyes, then hands","Read in our heads first, then clap."],[7,"Read-aloud · The Jazz Fly","Brain break, per the book guide."],[3,"Flash cards","Three more cards to finish."]]},{"b":"Shakers, woodblocks","i":[[3,"Flash cards","Warm up."],[1,"Instruments out & back","Hand out woodblocks and shakers in rest position; collect them the same way at the end."],[6,"Play it on sticks","Same patterns on woodblocks and shakers. Quiet."],[5,"Error hunt","Clap a written pattern with one mistake. Students catch it kindly."],[5,"Link to a song","Pattern as an ostinato under Rain, Rain: you sing, a small group plays it twice on woodblocks. Swap groups."]]},{"b":"No instruments (voices and body percussion)","i":[[3,"Flash cards","Warm up."],[10,"Write, trade, play","Each child writes four beats with at least two kinds (ta / ti-ti / sh). Trade and play your partner’s."],[3,"Challenge","Play your pattern twice with no gap. That is an ostinato."],[4,"Close + Check","Perform two student patterns as a class. Go through the Check list and stamp."]]}],"18":[{"b":"No instruments (voices and body percussion)","i":[[4,"Echo warmup","You clap four, class echoes. A student volunteer claps four, class echoes."],[6,"Read-aloud · Jam, Too?","Hook before the recipe, per the book guide."],[4,"The recipe","Four beats. At least two of ta, ti-ti, rest. Must be echoable."],[6,"Practice alone","Write. Clap. Fix. If you can’t clap it, change it."]]},{"b":"No instruments (voices and body percussion)","i":[[3,"Echo warmup","Warm up."],[3,"How we share","Child claps, class echoes once, two-clap applause, next child."],[3,"If they freeze","All tas still counts. Pride over complexity."],[11,"Project 3 · share (first rows)","As many students as time allows. Note who still needs a turn."]]},{"b":"No instruments (voices and body percussion)","i":[[3,"Echo warmup","Warm up."],[10,"Project 3 · share (remaining students)","Everyone who has not shared yet. Collect papers."],[3,"Challenge","Two friends play one pattern as a quiet ostinato under Pease Porridge Hot."],[4,"Close + Check","Name the musical bravery, not the fanciest pattern. Go through the Check list and stamp Project 3."]]}],"19":[{"b":"1–2 xylophones + mallets","i":[[4,"Mountain and valley","Siren up, stretch tall. Siren down, crouch. Four times."],[5,"High is not loud","A mouse can be high and quiet. A drum can be low and soft."],[6,"Two notes only","Play a high G and a low C on the xylophone you carry in (or the site’s Music Studio piano on the classroom screen). Students point up or down, then sing “high” and “low.”"],[5,"Read-aloud · Up, Up, Down","Per the book guide."]]},{"b":"1–2 xylophones + mallets","i":[[3,"Mountain and valley","Warm up."],[7,"Xylophone turns","Two children at a time play high and low on the 1–2 xylophones at the front while the class shows it with their bodies beside their desks. Rotate players. No xylophone today? Use the site’s Music Studio piano on the classroom screen."],[6,"Song: Star Light","Listen for the drop and trace it in the air. Use the score on the page."],[4,"Two notes only","Quick replay on the xylophone, some notes soft and some strong: we’re listening for pitch, not volume."]]},{"b":"1–2 xylophones + mallets","i":[[3,"Star Light","Sing and trace."],[10,"Sort the sound","Mixed high and low: stand beside your desk for high, sit for low. Then pairs take turns at the 1–2 xylophones at the front to quiz each other while the rest of the class shows high or low with their bodies."],[2,"Challenge","Sing a so–mi “cuckoo” for the class to echo."],[5,"Close + Check","“If I sing softly, can it still be high?” Yes. Go through the Check list and stamp."]]}],"20":[{"b":"No instruments (voices and body percussion)","i":[[4,"Finger paint the air","Slow so–mi–so; draw it in the air. Then a line that only goes up, then only down."],[7,"Read-aloud · Little Melba and Her Big Trombone","Hook, per the book guide. Read up to Melba’s radio solo."],[5,"Contour means the shape","Draw hill, slide down, flat road on the board."],[4,"Stay means repeats","Same pitch = flat line. Still a melody."]]},{"b":"No instruments (voices and body percussion). Music Studio on the screen","i":[[3,"Finger paint the air","Warm up."],[7,"Map a known song","Draw See-Saw together, then Rain, Rain."],[5,"Same or different shape","Sing two patterns (or play them on the site’s Music Studio piano on the classroom screen). Thumbs up if the maps match."],[5,"Practice studio · piano","Play short up/down tunes on the site’s Music Studio piano on the classroom screen; the class draws them in the air."]]},{"b":"No instruments (voices and body percussion)","i":[[3,"Same or different shape","Warm up."],[10,"Draw the tune","Listen three times to a short pattern and draw one contour line. Share with a neighbour."],[2,"Challenge","Sing a friend’s map without the words."],[5,"Close + Check","Hold up two student maps; class sings them. Go through the Check list and stamp."]]}],"21":[{"b":"No instruments (voices and body percussion). Music Studio on the screen","i":[[4,"Sign and sing","Silent signs, class sings. Sung pattern, class signs. So–mi only."],[6,"Three songs, one pair of pitches","Rain, Rain · See-Saw · Star Light. Hum one; which song is it?"],[6,"Fix the sticky phrase","Echo the tricky phrase three times, then go back to the song."],[4,"Practice studio · piano","Play so (G) and mi (E) on the site’s Music Studio piano on the classroom screen while the class signs."]]},{"b":"Shakers","i":[[3,"Sign and sing","Warm up."],[5,"Alone, then group","A volunteer sings a so–mi hello; the group answers. Sitting solos are fine."],[1,"Instruments out & back","Hand out a few shakers in rest position; collect them the same way at the end."],[5,"Add a beat","Laps on the beat while we sing. Then a few shakers keep the beat."],[6,"Book · Rain, Rain, Go Away!","Sing the book, with signs."]]},{"b":"No instruments (voices and body percussion)","i":[[3,"Sign and sing","Warm up."],[10,"Song medley","All three songs with signs. Pick one to perform standing in concert posture."],[3,"Challenge","A student leads See-Saw with only their hands."],[4,"Close + Check","Which song felt easiest? Go through the Check list and stamp."]]}],"22":[{"b":"No instruments (voices and body percussion)","i":[[4,"So–mi neighbour","Review so–mi, then so–la–so–mi on “loo.”"],[6,"La is a step above so","Show the la sign higher than so. Sing it lightly with your voice. It shouldn’t punch."],[5,"Read-aloud · Up, Up, Down","Per the book guide."],[5,"Do not pile on do yet","Three pitches is plenty. Echo so–la–so–mi patterns."]]},{"b":"No instruments (voices and body percussion)","i":[[3,"So–mi neighbour","Warm up."],[7,"Bounce High","Teach by echo with a class name."],[5,"Sign the new note only","First pass: sign la only. Then the whole song."],[5,"Lucy Locket","Sing it from the scores and listen for la."]]},{"b":"No instruments. Soft ball or beanbag","i":[[3,"Bounce High","Sing and sign."],[10,"Name toss","Bounce High with a soft ball or beanbag. The named child can sing the last “Shiloh” as their own name."],[2,"Challenge","Improvise four beats on so–mi–la; class copies."],[5,"Close + Check","Silent signs so–la–so–mi; class sings. Go through the Check list and stamp."]]}],"23":[{"b":"No instruments (voices and body percussion)","i":[[4,"Copy my hands, no voice","Silent sign strings of four; copy, then add voice."],[7,"Read-aloud · Do Re Mi","Hook, per the book guide: read the start and end, summarise the middle."],[4,"Hands are the music","You’re reading, not guessing."],[5,"Four-beat reading","so so mi so · so la so mi. Rest is a closed fist. Slow."]]},{"b":"No instruments (voices and body percussion)","i":[[3,"Copy my hands, no voice","Warm up."],[5,"Four-beat reading","New patterns. Check your starting pitch on the site’s Music Studio piano on the classroom screen if needed."],[6,"Student conductor","A child signs a pattern; class sings. Stand them where all can see."],[6,"From signs to a song","Sign the first phrase of Rain, Rain, then Bounce High. Can they name it?"]]},{"b":"No instruments (voices and body percussion)","i":[[3,"Four-beat reading","Warm up."],[10,"Sign theatre","Three student conductors; class sings each pattern twice. Sneak in a known song phrase."],[2,"Challenge","Sign a whole phrase of Bounce High."],[5,"Close + Check","Eyes closed: you sing so–mi–la–so; they sign it. Go through the Check list and stamp."]]}],"24":[{"b":"1–2 xylophones + mallets","i":[[4,"Pitch bank","Sing so, mi, la as you point. Then tap them on the xylophone (G, E, A) or on the site’s Music Studio piano on the classroom screen."],[6,"Read-aloud · Mole Music","Hook, per the book guide."],[5,"Recipe","Four beats of so, mi, maybe la. Start and end on so or mi."],[5,"Voice first","Hum it before you write it. Model two tunes together."]]},{"b":"1–2 xylophones + mallets","i":[[3,"Pitch bank","Warm up."],[5,"Add rhythm they know","Each beat is ta or ti-ti; rest allowed."],[8,"Write and hum","Students compose at their desks, humming and signing. The 1–2 xylophones are a turn-taking spot for trying tunes (G = so, E = mi, A = la), and the site’s Music Studio piano on the classroom screen works too."],[4,"Star Light / Bounce High","Sing one from the scores as a model “finished” tune."]]},{"b":"1–2 xylophones + mallets","i":[[3,"Pitch bank","Warm up."],[6,"Write and hum · finish","Finish tunes. Keep the xylophone turn-taking spot going."],[5,"Share with a partner","Teach your partner; they echo. A few volunteers share."],[2,"Challenge","Tune over a ta ta ta ta beat a friend pats."],[4,"Close + Check","Collect tunes. Go through the Check list and stamp."]]}],"25":[{"b":"No instruments (voices and body percussion)","i":[[4,"Copy four","Clap clap pat pat; class copies. Two-finger palm tap for anyone who can’t snap."],[5,"Name the four","Clap, pat, stamp (gentle), snap or tap. We should still hear the song."],[4,"Safety","Stamps are quiet toe taps in the classroom, not jumps. Snaps are not at someone’s ear."],[7,"Read-aloud · Clap Your Hands","Brain break standing beside desks, per the book guide."]]},{"b":"No instruments (voices and body percussion)","i":[[3,"Copy four","Warm up."],[6,"Beat on the body","Sing Hello or Rain, Rain; beat in pats, then quiet toe taps. Try Teddy Bear from the scores."],[6,"Pattern on the body","ti-ti ta rest as clap-clap pat open."],[5,"Copy four (extended)","Students lead four-beat body patterns for the class."]]},{"b":"No instruments (voices and body percussion)","i":[[3,"Copy four","Warm up."],[10,"Body ostinato","A small group repeats clap-pat-clap-rest while the class sings Pease Porridge Hot. Swap groups."],[3,"Challenge","Invent a four-beat body pattern and teach your row."],[4,"Close + Check","Freeze in a body-percussion statue. Go through the Check list and stamp."]]}],"26":[{"b":"Hand drum, shakers, woodblocks, triangle, tambourine","i":[[4,"Rest position","Pass out shakers and woodblocks. Pick up, play four beats, rest."],[6,"Read-aloud · Zin! Zin! Zin! A Violin","Hook, per the book guide. Instruments stay in rest position."],[5,"Passing out and in","You hand out, about a minute; they don’t help themselves. Collect the same way."],[5,"One job today: the beat","Even sounds with the hand drum or with you."]]},{"b":"Hand drum, shakers, woodblocks, triangle, tambourine","i":[[3,"Rest position","Hand out instruments (about 1 min) and practise the loop."],[7,"How each one speaks","Woodblocks tap, shakers shake once per beat, triangle rings and waits, hand drums open palm, tambourine taps."],[5,"Quiet is a skill","Play under Star Light so the song stays the star."],[5,"Practice studio · quiz","Play the page’s sound quiz together."]]},{"b":"Hand drum, shakers, woodblocks, triangle, tambourine","i":[[2,"Rest position","Hand out instruments (about 1 min) and warm up the pick-up / play / rest loop."],[10,"Pass the colours","Sit in a circle at the carpet (or desk groups) with one instrument type per group: hand drum, shakers, woodblocks, triangle + tambourine. Play the beat under a song, rest, then pass that type to the next group. About two minutes each."],[3,"Challenge","Eyes on the conductor, not the instrument."],[5,"Close + Check","Collect. Count. Thank the instruments. Go through the Check list and stamp."]]}],"27":[{"b":"Mystery bag: hand drum, shaker, woodblock, triangle, tambourine","i":[[4,"Mystery bag","Play one hidden instrument (hand drum, shaker, triangle, woodblock); students guess."],[7,"Read-aloud · My Family Plays Music","Hook, per the book guide, with the real instruments ready."],[5,"Three cards for each","Word, picture, sound. Hand drum, shaker, triangle, woodblock."],[4,"How it makes the sound","Hit, shake, scrape. Let them name the action."]]},{"b":"Mystery bag: hand drum, shaker, woodblock, triangle, tambourine","i":[[3,"Mystery bag","Two new mystery sounds: the tambourine, and a shaker played slowly and then quickly."],[5,"High or low colour","Triangle vs hand drum. Link to week 19."],[5,"Use the studio","The page’s studio plays drum, shaker, bell, stick. Compare with the real ones."],[7,"Match the cards · first round","Play a sound; a student points to the picture card on the board."]]},{"b":"Mystery bag: hand drum, shaker, woodblock, triangle, tambourine","i":[[3,"Mystery bag","Warm up."],[9,"Match the table","Hear the sound, then point to its picture card on the board. Then a paper match on the worksheet, and the site quiz on the projector."],[3,"Challenge","A student is the mystery player; class guesses with eyes closed."],[5,"Close + Check","Four sounds, four names, fast. Go through the Check list and stamp."]]}],"28":[{"b":"No instruments. Paper and a few found objects","i":[[5,"Paper orchestra","Tap, wave, rip a tiny corner if allowed. Freeze. Favourite sound?"],[4,"Found sound has rules","We don’t wreck school things or use friends as drums."],[6,"Read-aloud · Max Found Two Sticks","Hook, per the book guide. The class knows it from week 12."],[5,"Same object, new way","A pencil can tap, scrape, or roll."]]},{"b":"No instruments. Paper and a few found objects","i":[[3,"Paper orchestra","Warm up."],[7,"Build a tiny piece","Four beats of found sound as an ostinato under Acka Backa."],[6,"Invented instrument","Two objects together. Name it. Play a beat. Bow."],[4,"Same object, new way","Share one new way per table."]]},{"b":"No instruments. Paper and a few found objects","i":[[3,"Paper orchestra","Warm up."],[9,"Composer pairs","Pick two found sounds, write a four-beat idea (icons), perform once."],[3,"Challenge","Invented instrument plays only on the rests of a class pattern."],[5,"Close + Check","Leave the homeroom better than we found it. Go through the Check list and stamp."]]}],"29":[{"b":"Hand drum","i":[[4,"Follow my feet","Step in place beside your desk: slow, faster, freeze. Then clap piano (quiet) and forte (loud)."],[7,"Read-aloud · Trombone Shorty","Hook, per the book guide: key pages, summarise the middle."],[4,"Two pairs","Fast/slow is speed. Loud/quiet is volume. Keep them apart."],[5,"The song stays the same","Rain, Rain slow, then faster. Same tune."]]},{"b":"Hand drum","i":[[3,"Follow my feet","Warm up with the hand drum, stepping in place."],[5,"The song stays the same","Quiet vs strong. Try Hickory Dickory Dock from the scores."],[6,"Conductor tools","Small hand = quiet, big hand = stronger. Slow scoop vs quick tick."],[3,"Piano and forte","Say the words once, then play piano and forte on the hand drum."],[3,"Four-card song · first try","You hold the cards."]]},{"b":"Hand drum","i":[[3,"Follow my feet","Warm up."],[10,"Four-card song","A student helper shows a card; class sings Teddy Bear or Rain, Rain that way. Rotate helpers."],[2,"Challenge","Change in the middle of the song."],[5,"Close + Check","One child conducts quiet to loud on a long loo. Go through the Check list and stamp."]]}],"30":[{"b":"No instruments. Recordings on the classroom screen","i":[[4,"How we sit to listen","Still bodies, eyes on the speaker. Name the listening job."],[5,"Respect first","We listen. We don’t pretend, costume, or make up chants. Credit shared songs by name."],[7,"Read-aloud · We Belong to the Drum","Hook in listening posture, per the book guide. A story to listen to, not a song to copy."],[4,"Optional story · The listening chair","Read the short story on the page."]]},{"b":"No instruments. Recordings on the classroom screen","i":[[3,"How we sit to listen","Reset listening posture."],[6,"One focus listen","45–90 seconds. Drum or fiddle? Fast or slow? For dancing or sitting?"],[6,"Métis fiddle and jig","Listen to a jig on the classroom screen. Students may pat the beat at their desks. Listening is the job."],[5,"One focus listen (repeat)","Play the same piece again with a new question."]]},{"b":"No instruments. Recordings on the classroom screen","i":[[3,"How we sit to listen","Warm up."],[5,"Many cultures","A second short piece the class has a real link to, same respectful frame."],[8,"Draw what you heard","Listening map: dots for drum, line for voice or fiddle. Share one noticing with a partner."],[4,"Close + Check","Credit the artists again. Go through the Check list and stamp."]]}],"31":[{"b":"1 woodblock","i":[[4,"Copy or change","Clap a pattern; second time is identical or one beat different. Thumbs."],[6,"Phrases are musical sentences","Rain, Rain phrase 1, phrase 2. Same? Mostly, with a small tail."],[4,"A song with a chorus","Hold SAME on a repeated line (a hello song works)."],[6,"Read-aloud · We're Going on a Bear Hunt","Brain break; listen for the lines that come back (same)."]]},{"b":"1 woodblock","i":[[3,"Copy or change","Warm up on woodblock."],[5,"Call and response is a form","You call, class responds. Name the shape."],[7,"Map it with colour","Blue card when a phrase returns, yellow for new. Try Lucy Locket."],[5,"Card holders · first try","You hold SAME / DIFFERENT."]]},{"b":"1 woodblock","i":[[3,"Copy or change","Warm up."],[10,"Card holders","Two students hold SAME and DIFFERENT; class sings; cards pop up. Switch helpers."],[2,"Challenge","Make a call; class responds with something different on purpose."],[5,"Close + Check","Echo-like song vs two-idea song. Go through the Check list and stamp."]]}],"32":[{"b":"No instruments (voices and body percussion)","i":[[4,"Name call","“Charlie over the ocean”; class echoes."],[5,"Read-aloud · Polar Bear, Polar Bear","Hook: the question-and-answer pattern is the lesson."],[4,"Jobs","Leader waits after the call. The group doesn’t steal it."],[7,"Teach the song","Charlie Over the Ocean by echo, then call-response in two groups."]]},{"b":"No instruments (voices and body percussion)","i":[[3,"Name call","Warm up."],[6,"Teach the song","Call-response with a student leader."],[4,"Matching pitch still matters","The response is the call’s cousin, not a yell."],[4,"Kind leaders","Face the group, singing voice, thank the group."],[3,"Somebody's Knocking / Bounce High","Sing one from the scores as call-response."]]},{"b":"No instruments (voices and body percussion)","i":[[3,"Name call","Warm up."],[10,"Many leaders","As many student calls as time allows. Sitting leaders welcome."],[2,"Challenge","Invent a two-beat so–mi call; class answers so–mi–so."],[5,"Close + Check","Group response with no reminder. Go through the Check list and stamp."]]}],"33":[{"b":"No instruments (voices and body percussion)","i":[[4,"Memory lane","Hum four known songs; hands up for ones they feel ready to share."],[5,"Read-aloud · Pete the Cat: I Love My White Shoes","Per the book guide. Treat it as one candidate song."],[5,"What makes a good share song","We know it, we can start and stop, we still like it."],[6,"Vote with kindness","Choose the songs this class can do well together."]]},{"b":"Hand drum, woodblocks","i":[[3,"Memory lane","Sing the chosen songs once."],[1,"Instruments out & back","Hand out woodblocks in rest position; collect them the same way at the end."],[6,"The played piece","Choose one: body percussion ostinato, found-sound pattern, or a student four-beat pattern on woodblocks with your hand drum."],[5,"Write the order","Song, played piece, song. Put it on the board."],[5,"Practise the standing spots","Walking between pieces is the concert."]]},{"b":"Hand drum, woodblocks","i":[[3,"Memory lane","Warm up with piece 1."],[1,"Instruments out & back","Hand out woodblocks in rest position; collect them the same way at the end."],[10,"Draft run ×2","Stand, piece 1, piece 2, piece 3, small nod. Time it (under five minutes), fix one thing, run it again."],[2,"Challenge","A student announces piece 1 in a talking voice."],[4,"Close + Check","Program stays on the board. Go through the Check list and stamp."]]}],"34":[{"b":"No instruments (voices and body percussion)","i":[[4,"Bad audience / good audience","Model wiggling and talking, then still and watching. Keep it funny."],[7,"Read-aloud · Never Play Music Right Next to the Zoo","Hook, per the book guide."],[5,"Audience rules","Voices off, bodies on chairs, eyes on the players, clap at the end."],[4,"The clap","Two or three seconds, then rest. Practise it."]]},{"b":"Hand drum, woodblocks","i":[[3,"Bad audience / good audience","Quick replay."],[4,"Performer rules","Wait for the start. Keep going if you wobble. Smile at the end."],[1,"Instruments out & back","Hand out woodblocks in rest position; collect them the same way at the end."],[7,"Rehearse both jobs","Half performs piece 1, half is audience. Swap. Then piece 2."],[5,"O Canada phrase","Sing the phrase from the scores, standing as performers."]]},{"b":"Hand drum, woodblocks","i":[[2,"The clap","Warm up."],[1,"Instruments out & back","Hand out woodblocks in rest position; collect them the same way at the end."],[10,"Dress rehearsal ×2","Full order with real start and stop. You only conduct. Swap audience halves for the second run."],[2,"Challenge","One student starts the clap when the conductor’s hands drop."],[5,"Close + Check","One compliment each way. Go through the Check list and stamp."]]}],"35":[{"b":"Hand drum, woodblocks","i":[[4,"Body and breath","Shake out. Tall. One so–mi on loo. Quiet hand."],[3,"This is the share, not a new lesson","No new songs. Remind order, still feet, smile."],[1,"Instruments out & back","Hand out woodblocks in rest position; collect them the same way at the end."],[8,"Program run-through","Run the three pieces (Rain, Rain · Bounce High · Pease Porridge Hot, or your chosen order) once, fix one transition, and run the tricky piece again."],[4,"If the audience is late","Practise the fallback: sing the warm-up song sitting."]]},{"b":"Hand drum, woodblocks","i":[[4,"Body and breath","Warm up. Don’t tire them."],[1,"Instruments out & back","Hand out woodblocks in rest position; collect them the same way at the end."],[9,"You run it · Project 4 share","Announcer names piece 1. Conduct. Nod. Piece 2. Piece 3. Thank the audience."],[6,"After","Sit. Two specific comments from you."]]},{"b":"Hand drum, woodblocks","i":[[4,"Body and breath","Warm up."],[6,"Read-aloud · Zin! Zin! Zin! A Violin","Celebration read after the concert, per the book guide."],[1,"Instruments out & back","Hand out woodblocks in rest position; collect them the same way at the end."],[5,"Program again","Sing a favourite piece from the program, or run it once more for a walk-by audience if Class 2 had none."],[4,"Close + Check","Thank the musicians. Go through the Check list and stamp Project 4."]]}],"36":[{"b":"No instruments (voices and body percussion)","i":[[5,"Medley of us","Thirty seconds each of four favourite songs. Just the joy."],[6,"Name the big ideas","Beat. Long and short. High and low. Kind listening. Unison. Let them finish your sentences."],[6,"Read-aloud · Because","Per the book guide."],[3,"Thank you","Thank their voices and their waiting."]]},{"b":"Shakers, woodblocks","i":[[3,"Medley of us","Two favourites."],[1,"Instruments out & back","Hand out shakers and woodblocks in rest position; collect them the same way at the end."],[11,"Show what you know","Stations at desk groups: clap a four-beat card; sign so–mi; play a beat on a shaker or woodblock; sit as audience for a 20-second listen. Rotate."],[5,"A letter to next year’s class","One sentence: “In Grade 1 music you will…”. Scribe for those who need it."]]},{"b":"No instruments (voices and body percussion)","i":[[3,"Medley of us","Rain, Rain and Bounce High."],[10,"Portfolio page","Worksheet, then one last song standing. Optional: teach a so–mi hello to a stuffed guest."],[2,"Challenge","Practise teaching a grown-up the quiet hand."],[5,"Close + Check","Sing the week 1 hello song. Go through the Check list. Stamp the year."]]}]};
